// Implementing a miniature parser and interpreter to validate simple text formats
enum ASTNode {
    Digit,
    Alpha,
}

fn validate(input: &str, ast: &[ASTNode]) -> bool {
    let mut chars = input.chars();
    for node in ast {
        let c = match chars.next() {
            Some(val) => val,
            None => return false,
        };
        match node {
            ASTNode::Digit => if !c.is_ascii_digit() { return false; },
            ASTNode::Alpha => if !c.is_alphabetic() { return false; },
        }
    }
    true
}
